// เรียกความจำ Global
const sd = $getWorkflowStaticData('global');

// ดึง UserId จาก Webhook (ต้นทาง)
const userId = $('Webhook').item.json.body.events[0].source.userId;

// ลบข้อมูลสถานะทิ้ง (จบงาน)
if (userId && sd[userId]) {
  delete sd[userId];
}

return [{ json: { status: "State Cleared", userId: userId, finished: true } }];

const now = new Date();
const returnData = [];

// วนลูปเช็ค Ticket ทุกบรรทัด
for (const item of $input.all()) {
    const data = item.json;

    // --- โซนจับคู่ชื่อคอลัมน์ (แก้ให้ตรงกับหัวตารางจริงของคุณ 100%) ---
    const status = data['status']; 
    // ชื่อยาวๆ ของ due_at
    const dueAtRaw = data['due_at (created_at + sla_minutes)']; 
    // ชื่อยาวๆ ของ notified overdue
    const notifiedAt = data['notified_overdue_at (เวลาที่เคยแจ้งตก SLA)'];
    // ชื่อยาวๆ ของ channel (ที่เก็บ userId/groupId)
    // *สำคัญ: ถ้าใน Sheet คุณเก็บ ID ไว้ช่องอื่น ให้แก้ตรงนี้ครับ
    // แต่จาก workflow เก่า เราเก็บลงช่อง channel หรือ line_to ลองเช็คดูครับ
    // สมมติว่าเก็บใน channel ตามชื่อคอลัมน์ที่คุณให้มา:
    const lineTo = data['channel (LINE/Email/etc. แล้วแต่คุณ)']; 
    // ------------------------------------------------

    // 1. ถ้าปิดเคสแล้ว หรือไม่มีคนรับผิดชอบ (ไม่มี lineTo) ให้ข้ามไป
    if (status === 'Resolved' || status === 'Closed') continue;

    // 2. แปลงวันที่ (ถ้าไม่มีวันที่ ให้ข้าม)
    if (!dueAtRaw) continue;
    const dueAt = new Date(dueAtRaw);
    if (isNaN(dueAt.getTime())) continue;

    // 3. คำนวณเวลาที่เกิน (นาที)
    const diffMs = now - dueAt;
    const overdueMinutes = Math.floor(diffMs / 60000);

    // 4. เงื่อนไข: เกินเวลา (>0) และ ยังไม่เคยแจ้งเตือน (!notifiedAt)
    // หมายเหตุ: เช็ค overdueMinutes > 0 คือเกินเวลาแล้ว
    if (overdueMinutes > 0 && (!notifiedAt || notifiedAt.toString().trim() === '')) {

        // เตรียมข้อความ
        const priority = data['priority (P1/P2/P3)'] || '-';
        const type = data['type (Incident/Request)'] || '-';
        const subject = data['Subject'] || '-';

        const msg = `🚨 SLA Ticket Overdue 🚨\n\n` +
                    `Ticket ID: ${data['ticket_id']}\n` +
                    `Type: ${type}\n` +
                    `Priority: ${priority}\n` +
                    `Status: ${status}\n\n` +
                    `⚠️ เกินกำหนดมาแล้ว: ${overdueMinutes} นาที\n` +
                    `อาการ: ${subject}`;

        returnData.push({
            json: {
                ...data,
                overdue_minutes: overdueMinutes,
                message_text: msg,
                line_to: lineTo, // ส่งค่านี้ไปให้ Node แจ้งเตือนใช้
                // ใช้ค่า row_number ที่ติดมากับ Google Sheet Node
                targetRow: data.row_number || (item.index + 2) 
            }
        });
    }
}

return returnData;

const returnData = [];

// วนลูปเช็ค Ticket ทุกบรรทัด
for (const item of $input.all()) {
    const data = item.json;

    // --- โซนจับคู่ชื่อคอลัมน์ ---
    const status = data['status']; 
    const notifiedClosed = data['notified_closed_at (เวลาที่เคยแจ้งปิดงานแล้ว)']; // *เช็คชื่อหัวตารางใน Sheet ให้ตรงนะครับ*
    const lineTo = data['channel (LINE/Email/etc. แล้วแต่คุณ)'];
    // ------------------------------------------------

    // เงื่อนไข: 
    // 1. สถานะเป็น Resolved หรือ Closed
    // 2. ยังไม่เคยแจ้งเตือน (!notifiedClosed)
    // 3. (สำคัญ) ต้องมี User ID (lineTo) ด้วย ไม่งั้นส่งไม่ได้
    if (
        (status === 'Resolved' || status === 'Closed') && 
        (!notifiedClosed || notifiedClosed.toString().trim() === '') &&
        lineTo // <--- เพิ่มบรรทัดนี้: ถ้าไม่มี ID ให้ข้าม
    ) {

        const ticketId = data['ticket_id'];
        const subject = data['Subject'] || '-';
        const fixDetail = data['Fix'] || 'ตรวจสอบและแก้ไขเรียบร้อยแล้ว';

        const msg = `✅ ปิดเคสเรียบร้อย (Resolved)\n\n` +
                    `Ticket ID: ${ticketId}\n` +
                    `อาการ: ${subject}\n\n` +
                    `🛠️ การแก้ไข: ${fixDetail}\n\n` +
                    `ขอบคุณที่ใช้บริการครับ 🙏`;

        returnData.push({
            json: {
                ...data,
                message_text: msg,
                line_to: lineTo,
                targetRow: data.row_number || (item.index + 2) 
            }
        });
    }
}

return returnData;

// ==========================================
// ส่วนที่ 1: รับข้อมูลจาก Tally
// ==========================================
const fields = $input.item.json.body.data.fields;
const result = {};

fields.forEach(field => {
  const key = field.label.trim();
  if (field.type === 'DROPDOWN' || field.type === 'MULTIPLE_CHOICE') {
    const selectedOption = field.options.find(opt => opt.id === field.value[0]);
    result[key] = selectedOption ? selectedOption.text : '-';
  } else if (field.type === 'FILE_UPLOAD') {
    result[key] = (field.value && field.value.length > 0) ? field.value[0].url : null;
  } else {
    result[key] = field.value || '-';
  }
});

const reporter = result['ชื่อผู้แจ้ง'] || 'Unknown';
let issueType = result['ประเภทปัญหา'] || 'Incident';
const subject = result['รายละเอียด/อาการ'] || '-';
const imageUrl = result['รูปภาพประกอบ'];

// ==========================================
// ส่วนที่ 2: Logic วิเคราะห์ Priority & SLA
// ==========================================
const text = subject.toLowerCase();

// Keyword Check
const failureKeywords = ['ไม่ได้', 'not', 'error', 'fail', 'พัง', 'เสีย', 'ล่ม', 'เข้าไม่', 'bug', 'ผิดพลาด', 'ไม่ขึ้น', 'ไม่แสดง', 'cannot'];
const requestKeywords = ['ขอ', 'request', 'เพิ่ม', 'ปรับ', 'แก้ไข', 'install', 'ติดตั้ง', 'สร้าง', 'create', 'new user', 'access'];

if (failureKeywords.some(k => text.includes(k))) {
    issueType = 'Incident';
} else if (requestKeywords.some(k => text.includes(k))) {
    issueType = 'Request';
}

// Priority Calculation
let priority = 'P3';
let sla_minutes = 480; 

if (issueType === 'Request') {
    priority = 'P4';
    sla_minutes = 1440; // 24 ชม.
} else {
    if (text.includes('ล่ม') || text.includes('ใช้งานไม่ได้ทั้งหมด') || text.includes('เข้าไม่ได้') || text.includes('down') || text.includes('critical')) {
        priority = 'P1';
        sla_minutes = 60; 
    } else if (text.includes('ไม่ได้') || text.includes('error') || text.includes('fail') || text.includes('ไม่ขึ้น')) {
        priority = 'P2';
        sla_minutes = 240; // 4 ชม.
    } else if (text.includes('บางส่วน') || text.includes('ช้า')) {
        priority = 'P3';
        sla_minutes = 480; 
    } else {
        priority = 'P4';
        sla_minutes = 1440; 
    }
}

// SLA Text Display
let slaText = "";
if (sla_minutes >= 60) {
    const hrs = Math.floor(sla_minutes / 60);
    const mins = sla_minutes % 60;
    slaText = mins === 0 ? `${hrs} ชั่วโมง` : `${hrs} ชม. ${mins} นาที`;
} else {
    slaText = `${sla_minutes} นาที`;
}

// ==========================================
// ส่วนที่ 3: จัดการเวลา และข้อมูลเสริม (New Features ✨)
// ==========================================
const now = new Date();

function formatDateTime(dateObj) {
    const d = String(dateObj.getDate()).padStart(2, '0');
    const m = String(dateObj.getMonth() + 1).padStart(2, '0');
    const y = dateObj.getFullYear();
    const hr = String(dateObj.getHours()).padStart(2, '0');
    const min = String(dateObj.getMinutes()).padStart(2, '0');
    return `${d}/${m}/${y} ${hr}:${min}`;
}

