const dueTimeStr = formatDateTime(due_at);

// Ticket ID Generation
const y_id = now.getFullYear().toString().slice(2);
const m_id = String(now.getMonth() + 1).padStart(2, '0');
const d_id = String(now.getDate()).padStart(2, '0');
