if (priority === 'P1') {
    headerColor = "#FF3333"; headerText = "🚨 Critical Incident (P1)";
} else if (priority === 'P2') {
    headerColor = "#FF9933"; headerText = "⚠️ High Priority Incident";
} else if (priority === 'P3') {
