// 1. แกะข้อมูลจาก Tally
const fields = $input.item.json.body.data.fields;
const result = {};

fields.forEach(field => {
  const key = field.label.trim();
  if (field.type === 'DROPDOWN' || field.type === 'MULTIPLE_CHOICE') {
    const selectedOption = field.options.find(opt => opt.id === field.value[0]);
    result[key] = selectedOption ? selectedOption.text : '-';
  } else if (field.type === 'FILE_UPLOAD') {
    result[key] = (field.value && field.value.length > 0) ? field.value[0].url : null;
  } else {
    result[key] = field.value || '-';
  }
});

// ส่งออกเฉพาะข้อมูลที่จำเป็นให้ AI วิเคราะห์
return {
  Reporter: result['ชื่อผู้แจ้ง'] || 'Unknown',
  User_Selected_Type: result['ประเภทปัญหา'] || 'Incident', 
  Subject: result['รายละเอียด/อาการ'] || '-',
  Image: result['รูปภาพประกอบ'] || null
};

// 1. รับค่าจาก Gemini (Clean JSON)
const aiResponse = $input.item.json.output || $input.item.json.text || "{}";
const cleanJson = aiResponse.replace(/```json/g, '').replace(/```/g, '').trim();
let ai = {};

try {
    ai = JSON.parse(cleanJson);
} catch (e) {
    ai = { analyzed_type: 'Incident', priority: 'P3', summary: 'AI Parse Error', assignee: 'IT Support' };
}

